import json
import collections

# Retrieve parameters directly from the globally injected 'input_data' dictionary
map_id = input_data['map_id']
start_x = int(input_data['start_x'])
start_y = int(input_data['start_y'])
target_x = int(input_data['target_x'])
target_y = int(input_data['target_y'])

def find_path():
    impassable = set()
    plateau = set()
    transitions = {}

    # Define map-specific boundaries and blockages based on empirical data:
    if map_id == "0_10": # Saffron City
        # Main buildings and fences
        # Add fences on column 3:
        for y in range(17, 30):
            impassable.add((3, y))
        # Mr. Psychic's house
        for x in range(26, 32):
            for y in range(25, 30):
                impassable.add((x, y))
        # Pokemon Center
        for x in range(5, 11):
            for y in range(25, 29):
                impassable.add((x, y))

    elif map_id == "0_202": # Rocket Hideout B4F
        # Office walls and tables on Row 4
        for x in range(18, 28):
            impassable.add((x, 4))
        # Guard posts and other walls:
        for y in range(1, 15):
            impassable.add((21, y)) # Column 21 partition wall

    # Spinner definitions for Rocket Hideout floors (Map 0_199 to 0_202):
    # Spinners map a tile (x, y) to a sliding direction: "Up", "Down", "Left", "Right"
    spinners = {}
    stop_tiles = set()

    if map_id == "0_200": # Rocket Hideout B2F Spinner Maze
        # Define spinners:
        spinners[(17, 11)] = "Left"
        spinners[(13, 18)] = "Left"
        spinners[(11, 18)] = "Down"
        spinners[(13, 22)] = "Left"
        spinners[(9, 22)] = "Down"
        spinners[(10, 25)] = "Right"

        # Stop tiles:
        stop_tiles.update([(1, 9), (9, 16), (15, 18), (11, 20), (9, 24), (14, 25)])

    # Safari Zone Maps:
    if map_id == "0_220": # Safari Zone Center
        # Width: 30, Height: 26
        # Rest House 1: Columns 13-14, Row 22
        for x in [13, 14]:
            impassable.add((x, 22))
        # Gatehouse barrier: Row 24 Column 15 is solid
        impassable.add((15, 24))
        # Row 15/16 Tree Wall: Columns 2 to 17
        for x in range(2, 18):
            impassable.add((x, 15))
            impassable.add((x, 16))
        # Row 9 Fence: Columns 22 to 27
        for x in range(22, 28):
            impassable.add((x, 9))
        # Central Lake: Rows 8-13, Columns 8-21
        for x in range(8, 22):
            for y in range(8, 14):
                impassable.add((x, y))
        # Fence/Trees: Columns 28-29, Row 9
        for x in [28, 29]:
            impassable.add((x, 9))

    elif map_id == "0_217": # Safari Zone East
        # Width: 30, Height: 26
        # Rest House 1: Columns 5-6, Rows 22-23
        for x in [5, 6]:
            for y in [22, 23]:
                impassable.add((x, y))
        # Row 20 and 25 fences
        for x in range(0, 30):
            impassable.add((x, 20))
            impassable.add((x, 25))
        # Row 6 Ground-Level Blockage: Column 0 to 10 is blocked on ground
        for x in range(0, 11):
            impassable.add((x, 6, 0))
            impassable.add((x, 5, 0))
        # Row 2 Column 0 solid cliff
        impassable.add((0, 2))
        # Water: Columns 16-19, Rows 16-17
        for x in range(16, 20):
            for y in [16, 17]:
                impassable.add((x, y))

        # Define Plateau area
        for x in range(11, 23):
            for y in range(11, 22):
                if not (16 <= x <= 19 and 16 <= y <= 17):
                    plateau.add((x, y))
        for x in range(11, 23):
            for y in range(4, 7):
                plateau.add((x, y))

        def add_trans(pt1, pt2):
            if pt1 not in transitions: transitions[pt1] = set()
            if pt2 not in transitions: transitions[pt2] = set()
            transitions[pt1].add(pt2)
            transitions[pt2].add(pt1)

        add_trans((20, 21, 0), (20, 20, 1))
        add_trans((12, 22, 0), (12, 21, 1))
        add_trans((12, 8, 0), (12, 7, 0))
        add_trans((12, 7, 0), (12, 6, 1))
        add_trans((17, 8, 0), (17, 7, 0))
        add_trans((17, 7, 0), (17, 6, 1))

    elif map_id == "0_218": # Safari Zone North
        # Width: 40, Height: 36
        # Water lake: Columns 8-11, Rows 8-13
        for x in range(8, 12):
            for y in range(8, 14):
                impassable.add((x, y))
        # Water lake: Columns 4-7, Rows 14-18
        for x in range(4, 8):
            for y in range(14, 19):
                impassable.add((x, y))
        # Row 11: Columns 18-24 are solid wall
        for x in range(18, 25):
            impassable.add((x, 11))
        # Row 4: Columns 11-19 are solid tree wall
        for x in range(11, 20):
            impassable.add((x, 4))
        # Row 34: Columns 10-19 are solid building
        for x in range(10, 20):
            impassable.add((x, 34))

        # Plateau areas:
        # Western Plateau: x in range [16, 24], y in range [20, 22]
        for x in range(16, 25):
            for y in range(20, 23):
                plateau.add((x, y))
        # Eastern Plateau: x in range [28, 34], y in range [15, 26]
        for x in range(28, 35):
            for y in range(15, 27):
                plateau.add((x, y))

        def add_trans(pt1, pt2):
            if pt1 not in transitions: transitions[pt1] = set()
            if pt2 not in transitions: transitions[pt2] = set()
            transitions[pt1].add(pt2)
            transitions[pt2].add(pt1)

        add_trans((22, 24, 0), (22, 23, 0))
        add_trans((22, 23, 0), (22, 22, 1))
        for y in range(22, 28):
            add_trans((16, y+1, 0), (16, y, 0 if y > 22 else 1))
        add_trans((28, 28, 0), (28, 27, 0))
        add_trans((28, 27, 0), (28, 26, 1))
        add_trans((34, 16, 0), (34, 15, 0))
        add_trans((34, 15, 0), (34, 14, 1))

    elif map_id == "0_219": # Safari Zone West
        # Width: 30, Height: 26
        # Water southwest/northwest corridor blockages:
        # Columns 2 and 3 blocked at Row 13
        for x in [2, 3]:
            impassable.add((x, 13))
        # Column 1 blocked at Row 13-14 by trees
        for y in [13, 14]:
            impassable.add((1, y))
        # Columns 4-8 along Row 13 blocked by water
        for x in range(4, 9):
            impassable.add((x, 13))
        # Column 9 blocked by water on Rows 10-13
        for y in range(10, 14):
            impassable.add((9, y))
        # Column 10 blocked at Row 11 by Rest House 3
        impassable.add((10, 11))
        # Column 14 on Rows 12-15 blocked by cliff wall
        for y in range(12, 16):
            impassable.add((14, y))
        # Column 24 (Rows 1-13) is solid tree wall
        for y in range(1, 14):
            impassable.add((24, y))
        # Column 17 cliff wall on ground (elevation=0): Rows 6-13
        for y in range(6, 14):
            impassable.add((17, y, 0))
            impassable.add((16, y, 0)) # Block horizontal passage between 16 and 17

        # Plateau area: Columns 6 to 21, Rows 6 to 16
        for x in range(6, 22):
            for y in range(6, 17):
                plateau.add((x, y))

        def add_trans(pt1, pt2):
            if pt1 not in transitions: transitions[pt1] = set()
            if pt2 not in transitions: transitions[pt2] = set()
            transitions[pt1].add(pt2)
            transitions[pt2].add(pt1)

        for y in range(16, 20):
            add_trans((21, y+1, 0), (21, y, 0 if y > 16 else 1))
        for y in range(16, 20):
            add_trans((6, y+1, 0), (6, y, 0 if y > 16 else 1))
        add_trans((19, 9, 0), (18, 9, 0))
        add_trans((18, 9, 0), (17, 9, 0))
        add_trans((17, 9, 0), (16, 9, 1))

    # BFS Pathfinder with Spinner Simulation:
    start_elev = 1 if (start_x, start_y) in plateau else 0
    target_elev = 1 if (target_x, target_y) in plateau else 0

    queue = collections.deque([(start_x, start_y, start_elev, [])])
    visited = set([(start_x, start_y, start_elev)])

    max_x = 40 if map_id == "0_218" else 30
    max_y = 36 if map_id == "0_218" else 26

    while queue:
        cx, cy, ce, path = queue.popleft()
        if (cx, cy, ce) == (target_x, target_y, target_elev):
            return path

        for dx, dy, move in [(0, -1, "Up"), (0, 1, "Down"), (-1, 0, "Left"), (1, 0, "Right")]:
            nx, ny = cx + dx, cy + dy

            if not (0 <= nx < max_x and 0 <= ny < max_y):
                continue
            if (nx, ny) in impassable or (nx, ny, ce) in impassable:
                continue

            # Spinner sliding simulation:
            if (nx, ny) in spinners:
                sx, sy = nx, ny
                visited_slide = set([(sx, sy)])
                while (sx, sy) in spinners and (sx, sy) not in stop_tiles:
                    s_move = spinners[(sx, sy)]
                    sdx, sdy = {"Up": (0, -1), "Down": (0, 1), "Left": (-1, 0), "Right": (1, 0)}[s_move]
                    nsx, nsy = sx + sdx, sy + sdy
                    if not (0 <= nsx < max_x and 0 <= nsy < max_y) or (nsx, nsy) in impassable or (nsx, nsy) in visited_slide:
                        break
                    sx, sy = nsx, nsy
                    visited_slide.add((sx, sy))
                nx, ny = sx, sy

            # Determine next elevation (transition check)
            transition_found = False
            for (tx, ty, te) in transitions.get((cx, cy, ce), []):
                if (tx, ty) == (nx, ny):
                    ne = te
                    transition_found = True
                    break

            if not transition_found:
                ne = ce
                is_next_plateau = (nx, ny) in plateau
                if (ce == 1 and not is_next_plateau) or (ce == 0 and is_next_plateau):
                    continue

            if (nx, ny, ne) not in visited:
                visited.add((nx, ny, ne))
                queue.append((nx, ny, ne, path + [move]))

    return None

path = find_path()
if path is not None:
    print(json.dumps(path))
else:
    print(json.dumps([]))
